160	}
161	
162	function premiumRoundedInMhpcosFavor(premium: number): number {
163	  return Math.ceil(premium);
164	}
165	
166	export function quote(
167	  customer: Customer,
168	  items: Item[],
169	  previousContracts: number,
170	): number {
171	  const basePremium = policyBasePremium(items);
172	  const standing = { ...customer, previousContracts };
173	  const premium =
174	    basePremium +
175	    itemRiskSurcharges(items) +
176	    policyWideModifiers(standing, basePremium) +
177	    PROCESSING_FEE;
178	  return premiumRoundedInMhpcosFavor(premium);
179	}

